\copy (select o.payment_reference as reference, o.total_gross - o.amount_paid as amount_cents, o.currency, btrim(o.first_name || ' ' || o.last_name) as payer_name, o.order_number from orders o where o.status = 'AWAITING_PAYMENT' and o.payment_method = 'BANK_TRANSFER' and o.payment_reference is not null and not o.is_test order by o.created_at, o.order_number) to stdout with csv header
